#version 300 es
precision highp float;

uniform sampler2D u_image0;
uniform vec2 u_resolution;

in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

void main() {
    // Original Gameboy horizontal resolution was 160 pixels
    float pixels = 160.0; 

    vec2 grid = vec2(pixels, pixels * (u_resolution.y / u_resolution.x));
    vec2 uv = floor(v_texCoord * grid) / grid;

    vec3 col = texture(u_image0, uv).rgb;
    float luma = dot(col, vec3(0.299, 0.587, 0.114));

    // Crunch the brightness into exactly 4 steps
    float stepVal = floor(luma * 3.99); 

    vec3 outCol;

    // Apply the classic 4 Gameboy Green colors
    if (stepVal == 0.0) outCol = vec3(0.06, 0.22, 0.06);      // Darkest
    else if (stepVal == 1.0) outCol = vec3(0.19, 0.38, 0.19); // Dark
    else if (stepVal == 2.0) outCol = vec3(0.55, 0.67, 0.20); // Light
    else outCol = vec3(0.61, 0.74, 0.20);                     // Lightest

    // Draw the tiny physical LCD gaps between the pixels
    vec2 pixelPos = fract(v_texCoord * grid);
    float border = step(0.05, pixelPos.x) * step(0.05, pixelPos.y);
    outCol *= mix(0.7, 1.0, border); // slightly darkens the gaps

    fragColor0 = vec4(outCol, 1.0);
}

