#version 300 es
precision highp float;

uniform sampler2D u_image0;
uniform vec2 u_resolution;

in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

float luma(vec3 color) {
    return dot(color, vec3(0.299, 0.587, 0.114));
}

void main() {
    vec2 uv = v_texCoord;
    vec2 dx = vec2(1.0 / u_resolution.x, 0.0);
    vec2 dy = vec2(0.0, 1.0 / u_resolution.y);

    // Sobel Edge Detection
    float s00 = luma(texture(u_image0, uv - dx - dy).rgb);
    float s10 = luma(texture(u_image0, uv - dy).rgb);
    float s20 = luma(texture(u_image0, uv + dx - dy).rgb);
    float s01 = luma(texture(u_image0, uv - dx).rgb);
    float s21 = luma(texture(u_image0, uv + dx).rgb);
    float s02 = luma(texture(u_image0, uv - dx + dy).rgb);
    float s12 = luma(texture(u_image0, uv + dy).rgb);
    float s22 = luma(texture(u_image0, uv + dx + dy).rgb);

    float sx = s00 + 2.0 * s01 + s02 - (s20 + 2.0 * s21 + s22);
    float sy = s00 + 2.0 * s10 + s20 - (s02 + 2.0 * s12 + s22);
    float edge = sqrt(sx * sx + sy * sy);

    // TWEAK THESE: Change the background or line colors!
    vec3 bgColor = vec3(0.05, 0.20, 0.60); // Classic Blueprint Blue
    vec3 lineColor = vec3(1.0, 1.0, 1.0);  // White Lines

    // Draw a subtle engineering grid in the background
    float grid = step(0.98, fract(uv.x * 20.0)) + step(0.98, fract(uv.y * 20.0 * (u_resolution.y / u_resolution.x)));
    bgColor += vec3(grid * 0.15); 

    // Mix the blue background with the white edges
    float edgeIntensity = clamp(edge * 2.5, 0.0, 1.0);
    vec3 finalColor = mix(bgColor, lineColor, edgeIntensity);

    fragColor0 = vec4(finalColor, 1.0);
}

