precision highp float;

uniform sampler2D u_image0;
uniform vec2 u_resolution;

in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

// Function to curve the screen
vec2 curve(vec2 uv) {
    uv = (uv - 0.5) * 2.0;
    uv *= 1.05; // zoom out slightly to see the TV borders
    uv.x *= 1.0 + pow((abs(uv.y) / 6.0), 2.0);
    uv.y *= 1.0 + pow((abs(uv.x) / 5.0), 2.0);
    uv  = (uv / 2.0) + 0.5;
    return uv;
}

void main() {
    vec2 uv = curve(v_texCoord);

    // Create black borders where the screen curves away
    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
        fragColor0 = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }

    // Sample colors with slight offset for Chromatic Aberration
    float colR = texture(u_image0, vec2(uv.x + 0.003, uv.y)).r;
    float colG = texture(u_image0, uv).g;
    float colB = texture(u_image0, vec2(uv.x - 0.003, uv.y)).b;

    // Add moving TV Scanlines
    float scanline = sin(uv.y * u_resolution.y * 1.5) * 0.04;
    vec3 col = vec3(colR, colG, colB) - scanline;

    // Add TV screen vignette (darken edges)
    float vig = uv.x * uv.y * (1.0 - uv.x) * (1.0 - uv.y);
    col *= pow(vig * 15.0, 0.25);

    fragColor0 = vec4(col, 1.0);
}

